package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	// 环境变量：没设置就用默认值
	os.Setenv("APP_ENV", "dev")
	env, ok := os.LookupEnv("APP_ENV")
	fmt.Println("运行环境:", env, "存在:", ok)

	name := os.Getenv("OUT_NAME")
	if name == "" {
		name = "report.txt"
	}

	// 临时工作目录，退出时整体删掉
	dir, err := os.MkdirTemp("", "demo")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)

	work := filepath.Join(dir, "work")
	if err := os.MkdirAll(work, 0755); err != nil {
		panic(err)
	}

	src := filepath.Join(work, "source.txt")
	if err := os.WriteFile(src, []byte("alpha\nbeta\ngamma\n"), 0644); err != nil {
		panic(err)
	}

	// 用 Scanner 逐行读，统计含 a 的行
	f, err := os.Open(src)
	if err != nil {
		panic(err)
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	hits := 0
	for scanner.Scan() {
		if strings.Contains(scanner.Text(), "a") {
			hits++
		}
	}
	if err := scanner.Err(); err != nil {
		panic(err)
	}
	fmt.Println("含 a 的行数:", hits)

	// 用 io.Copy 把源文件复制成目标文件
	dst := filepath.Join(work, name)
	out, err := os.Create(dst)
	if err != nil {
		panic(err)
	}
	defer out.Close()

	in, err := os.Open(src)
	if err != nil {
		panic(err)
	}
	defer in.Close()

	n, err := io.Copy(out, in)
	if err != nil {
		panic(err)
	}
	fmt.Println("复制字节数:", n)

	// 改名，再看文件属性
	final := filepath.Join(work, "final.txt")
	if err := os.Rename(dst, final); err != nil {
		panic(err)
	}

	info, err := os.Stat(final)
	if err != nil {
		panic(err)
	}
	fmt.Println("文件:", filepath.Base(final), "扩展名:", filepath.Ext(final), "大小:", info.Size())

	// 读回来确认内容
	data, err := os.ReadFile(final)
	if err != nil {
		panic(err)
	}
	fmt.Println("内容:", strings.TrimSpace(string(data)))

	// 删掉不再需要的源文件
	if err := os.Remove(src); err != nil {
		panic(err)
	}
	fmt.Println("源文件已删除")
}
